import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const designRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const repositoryRoot = path.resolve(designRoot, "..");
const sourceRoot = path.join(repositoryRoot, "docs", "features");
const outputPath = path.join(designRoot, "src", "generated", "documentationArticles.ts");

function compareStable(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function normalizeLineEndings(value) {
  return value.replace(/\r\n?/gu, "\n");
}

async function collectMarkdown(directory) {
  const entries = (await readdir(directory, { withFileTypes: true })).sort((left, right) => compareStable(left.name, right.name));
  const files = [];
  for (const entry of entries) {
    const absolute = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...await collectMarkdown(absolute));
    else if (entry.isFile() && entry.name.toLocaleLowerCase().endsWith(".md")) files.push(absolute);
  }
  return files;
}

function articleTitle(body, relativePath) {
  const heading = body.split(/\r?\n/u).find((line) => /^#\s+\S/u.test(line));
  return heading ? heading.replace(/^#\s+/u, "").trim() : path.basename(relativePath, ".md");
}

async function buildSource() {
  const files = (await collectMarkdown(sourceRoot)).sort(compareStable);
  if (files.length === 0) throw new Error("No categorized documentation articles were found under docs/features");
  const articles = [];
  for (const absolute of files) {
    const relative = path.relative(sourceRoot, absolute).split(path.sep).join("/");
    const body = (await readFile(absolute, "utf8")).replace(/\r\n?/gu, "\n");
    const sourcePath = `features/${relative}`;
    articles.push({
      id: sourcePath,
      sourcePath,
      category: relative.split("/")[0] || "uncategorized",
      title: articleTitle(body, relative),
      body,
    });
  }

  return `// Generated by scripts/generate-documentation-bundle.mjs. Do not edit by hand.\nimport type { DocumentationArticle } from "@shared/documentation";\n\nexport const DOCUMENTATION_ARTICLES: readonly DocumentationArticle[] = ${JSON.stringify(articles, null, 2)};\n`;
}

const expected = await buildSource();
if (process.argv.includes("--check")) {
  let actual = "";
  try {
    actual = normalizeLineEndings(await readFile(outputPath, "utf8"));
  } catch {
    throw new Error(`Documentation bundle is missing: ${path.relative(repositoryRoot, outputPath)}. Run npm run docs:bundle.`);
  }
  if (actual !== expected) {
    throw new Error("Documentation bundle is stale. Run npm run docs:bundle and commit the generated file.");
  }
} else {
  await writeFile(outputPath, expected, "utf8");
}
